//! 🧪️ The actual producer carries genuine original directory custody across one changed immutable path.
#![allow(dead_code)]
/// 📏️ Authored retirement body: large enough for the fixed metadata of the nested sealed cursors plus one key page.
const BODY:usize=1<<16;
#[path="../../../../🧪️tests/support.rs"]mod support;
#[path="../../🧪️tests/helpers.rs"]mod helpers;
use helpers::*;
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value_control_contract::{RetainedCloneGrant,ValueRefusalKind};
use semio_framework_value_edit::{AdmittedNamedKeyIndex,KeyPreservingPersistentSet,NamedRankedSource,PersistentRankedKeys};
use semio_framework_value_persistent::list::persistent::{PersistentList,PersistentListBuilder};
use semio_framework_value_retained_clone::retained_clone::RetainedCloneSource;
use semio_framework_value_retirement::RetirementDemand;
use semio_framework_value_shared_issuance::{SealedShared,SharedIssuer};
use support::effect;
#[derive(semio_framework_value_derive::RetireOwned)]#[value(crate="::semio_framework_value_retained_clone")]pub(crate) struct TransferRow{pub(crate) key:String,pub(crate) payload:usize}
impl Clone for TransferRow{fn clone(&self)->Self{panic!("key-preserving changes must share every original unaddressed row")}}
fn transfer_key(row:&TransferRow)->&str{&row.key}
fn root(keys:&[String])->PersistentList<TransferRow>{let mut builder=PersistentListBuilder::new(keys.len());for(rank,text)in keys.iter().enumerate(){while !builder.accepts_row(){let d=builder.demand().unwrap();sync(grant(d),|e,r|builder.advance_into(e,r));}let mut row=Some(admit_funded(TransferRow{key:text.to_owned(),payload:rank},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<TransferRow>::birth_bytes(),depth:1,..Default::default()})).result.map_err(|(e,_)|e).unwrap().0);let d=builder.adopt_demand().unwrap();sync(grant(d),|e,r|builder.adopt_into(&mut row,e,r));}let d=builder.finish_demand().unwrap();sync(grant(d),|e,r|builder.finish_into(e,r));while !builder.output_ready(){let d=builder.demand().unwrap();sync(grant(d),|e,r|builder.advance_into(e,r));}let d=builder.take_demand().unwrap();let mut root=None;sync(grant(d),|e,r|builder.take_into(&mut root,e,r));let root=root.unwrap();effect::run(grant(builder.begin_close_demand()),|e|builder.begin_close_paid(e)).result.unwrap();close_loop(&mut builder,4096,false,|o|o.terminal_is_empty(),|o|o.close_demand(4096).unwrap(),|o,recover,effect,reply|if recover{o.recover_close_into(4096,effect,reply)}else{o.close_into(4096,effect,reply)});root}
fn close_owner(owner:&mut KeyPreservingPersistentSet<TransferRow>,totals:&mut(usize,usize)){owner.begin_close();let(b,r)=close_loop(owner,BODY,true,|o|o.terminal_is_empty(),|o|o.close_demand(BODY).unwrap(),|o,recover,effect,reply|if recover{o.recover_close_into(BODY,effect,reply)}else{o.close_into(BODY,effect,reply)});totals.0+=b;totals.1+=r;}
fn close_candidate(source:&mut RetainedCloneSource<PersistentList<TransferRow>>,totals:&mut(usize,usize)){let(b,r)=close_loop(source,BODY,false,|s|s.terminal_is_empty(),|s|s.next_close_demand(BODY).unwrap(),|s,recover,effect,reply|if recover{s.recover_close_into(BODY,effect,reply)}else{s.close_into(BODY,effect,reply)});totals.0+=b;totals.1+=r;}
fn run(keys:Vec<String>,rank:usize,replacement:String,accepted:bool,body:usize,cut:Option<usize>){
 let mut original=source(root(&keys));let input=PersistentRankedKeys{original:original.borrow(),key:transfer_key};let mut index=admit(&input);let directory=index.testkit_order().as_ptr();let addresses=(0..keys.len()).map(|i|input.original.get().get(i).unwrap()as*const TransferRow).collect::<Vec<_>>();let mut authored=source(admit_funded(TransferRow{key:replacement,payload:999},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<TransferRow>::birth_bytes(),depth:1,..Default::default()})).result.map_err(|(e,_)|e).unwrap().0);let authored_address=authored.borrow().get().get()as*const TransferRow;let d=index.project_demand(&input).unwrap();let mut slot=None;while !slot.as_ref().is_some_and(AdmittedNamedKeyIndex::ready){let d=index.project_demand(&input).unwrap();effect::settle(grant(d),|effect|index.project(&input,&mut slot,effect)).result.unwrap();}let d=KeyPreservingPersistentSet::<TransferRow>::constructor_demand();assert_eq!(d.copy_bytes,std::mem::size_of::<KeyPreservingPersistentSet<TransferRow>>()*2+std::mem::size_of::<AdmittedNamedKeyIndex>()*2);for denied in denies(d){let(v,bytes)=heap(||KeyPreservingPersistentSet::new(rank,transfer_key,&mut slot,denied).result.unwrap());assert!(v.is_none());assert!(slot.is_some());assert_eq!(bytes,(0,0));}let((mut owner,_),b,r)=exact(||KeyPreservingPersistentSet::new(rank,transfer_key,&mut slot,grant(d)).result.unwrap().unwrap(),|(_,p)|*p);assert!(slot.is_none());let mut totals=(b,r);let mut turns=0;
 while !owner.output_ready()&&!owner.refused()&&cut.is_none_or(|cut|turns<cut){let d=owner.demand(input.original,authored.borrow(),body).unwrap();assert!(d.copy_bytes<=BODY,"producer exceeds fixed metadata plus key page budget: {d:?}");for denied in denies(d){let(s,bytes,_)=outcome_turn(&mut owner,denied,|x,e|x.advance(input.original,authored.borrow(),e));let s=s.unwrap();assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(owner.demand(input.original,authored.borrow(),body).unwrap(),d);}let(result,(b,r),_)=outcome_turn(&mut owner,grant(d),|x,e|x.advance(input.original,authored.borrow(),e));{let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!((b,r),(p.retained_capacity_bytes,p.released_bytes));}totals.0+=b;totals.1+=r;if let Err(e)=result{let message=format!("{e:?}");assert_eq!(e.into_value_error().kind,ValueRefusalKind::InvalidValue,"{message}");assert!(owner.refused(),"{message}");}turns+=1;assert!(turns<1000000);}
 if cut.is_none(){assert_eq!(owner.output_ready(),accepted);assert_eq!(owner.refused(),!accepted);if accepted{let d=owner.take_demand().unwrap();for denied in denies(d){assert!(owner.take(denied).result.unwrap().is_none());}let(((mut candidate,mut transferred),_),b,r)=exact(||owner.take(grant(d)).result.unwrap().unwrap(),|(_,p)|*p);totals.0+=b;totals.1+=r;let next=PersistentRankedKeys{original:candidate.borrow(),key:transfer_key};assert_eq!(transferred.testkit_order().as_ptr(),directory);transferred.check_source(&next).unwrap();assert!(index.check_source(&next).is_err());assert!(transferred.check_source(&input).is_err());for i in 0..keys.len(){let old=input.original.get().get(i).unwrap();let new=next.original.get().get(i).unwrap();assert_eq!(old as*const TransferRow,addresses[i]);if i==rank{assert_eq!(new as*const TransferRow,authored_address);assert_eq!(new.payload,999);}else{assert_eq!(new as*const TransferRow,addresses[i]);assert_eq!(new.payload,i);}}assert_eq!(lookup(&next,&transferred,&keys[rank]).0,Some(rank));let(b,r)=close_index(&mut transferred);totals.0+=b;totals.1+=r;close_candidate(&mut candidate,&mut totals);}}
 close_owner(&mut owner,&mut totals);assert_eq!(totals.0,totals.1,"actual producer, candidate source and transferred directory ledger must settle without rebasing");assert_eq!(heap(||drop(owner)).1,(0,0));close_index(&mut index);close_source(&mut original);close_source(&mut authored);
}
#[test]
fn key_preserving_persistent_producer_transfers_original_directory_and_all_paid_cuts(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/♻️transfer/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for body in fixture["bodyBytes"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain(std::iter::once(None)){run(row["keys"].as_array().unwrap().iter().map(|key|key.as_str().unwrap().to_owned()).collect(),row["rank"].as_u64().unwrap()as usize,row["replacement"].as_str().unwrap().to_owned(),row["admitted"].as_bool().unwrap(),body.as_u64().unwrap()as usize,cut);}}}let keys=(0..257).map(|rank|format!("key{rank:08}")).collect::<Vec<_>>();run(keys.clone(),128,keys[128].clone(),true,BODY,None);}
#[test]
fn key_preserving_persistent_producer_checks_complete_original_utf8_and_foreign_sources(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/♻️transfer/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let prefix="x".repeat(fixture["prefixLength"].as_u64().unwrap()as usize);for suffix in ["é","é"]{run(vec![format!("{prefix}é")],0,format!("{prefix}{suffix}"),suffix=="é",1,None);}let keys=vec!["A".to_owned()];let mut original=source(root(&keys));let mut foreign=source(root(&keys));let input=PersistentRankedKeys{original:original.borrow(),key:transfer_key};let mut index=admit(&input);let d=index.project_demand(&input).unwrap();let mut slot=None;while !slot.as_ref().is_some_and(AdmittedNamedKeyIndex::ready){let d=index.project_demand(&input).unwrap();effect::settle(grant(d),|effect|index.project(&input,&mut slot,effect)).result.unwrap();}let((mut owner,_),born,released)=exact(||KeyPreservingPersistentSet::new(0,transfer_key,&mut slot,grant(KeyPreservingPersistentSet::<TransferRow>::constructor_demand())).result.unwrap().unwrap(),|(_,p)|*p);let mut authored=source(admit_funded(TransferRow{key:"A".to_owned(),payload:99},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<TransferRow>::birth_bytes(),depth:1,..Default::default()})).result.map_err(|(e,_)|e).unwrap().0);let(result,bytes)=heap(||owner.demand(foreign.borrow(),authored.borrow(),BODY));assert!(result.is_err());assert_eq!(bytes,(0,0));let mut totals=(born,released);close_owner(&mut owner,&mut totals);assert_eq!(totals.0,totals.1);close_index(&mut index);close_source(&mut original);close_source(&mut foreign);close_source(&mut authored);}
